 # Explicitly inherit helpers, not the previous suite's test methods.
 def screenshot(self,name,full=True):self.page.evaluate('document.activeElement?.blur()');self.page.locator('#workspace-status').evaluate('(e)=>e.textContent=""') if self.page.locator('#workspace-status').count() else None;self.page.screenshot(path=str(OUT/f'{base.base.ENGINE}-{name}.png'),full_page=full)
 def create_meet(self,sport='swimming'):
  self.basic(sport);self.nav('Schedule');p=self.page;p.get_by_role('button',name='Add Game/Meet/Tournament',exact=True).click();p.locator('#plan-title').fill('Synthetic weekend '+('meet' if sport=='swimming' else 'tournament'));p.locator('#plan-kind').select_option('meet' if sport=='swimming' else 'tournament');p.locator('#plan-start').fill('2026-11-20');p.locator('#plan-end').fill('2026-11-21');p.locator('#plan-note').fill('Parent-entered pool' if sport=='swimming' else 'Parent-entered gym');p.get_by_role('button',name='Add to schedule',exact=True).click();p.wait_for_selector('#schedule-list article')
 def add_session(self,name,day=0,sport='swimming'):
  p=self.page;box=p.locator('#schedule-list article').first.locator('.session-editor');box.locator('summary').click();box.get_by_label('Race / match name',exact=True).fill(name);box.get_by_label('Day offset (0 = first day)',exact=True).fill(str(day));box.get_by_label('Session start time (Mountain Time)',exact=True).fill('10:00');box.get_by_label('Session end time',exact=True).fill('10:10');
  if sport=='swimming':box.get_by_label('Race discipline (include distance and units)',exact=True).fill('100 yd freestyle');box.get_by_label('Pool course',exact=True).select_option('SCY')
  count=len(self.state()['profiles'][0]['plans'][0].get('sessions',[]));box.get_by_role('button',name='Add session',exact=True).click();p.wait_for_function('(n)=>JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].plans[0].sessions.length===n',arg=count+1)
