  p=self.page;p.goto(base.base.BASE+'/locked-in-demo');p.wait_for_selector('#lockedin-workflow input');before=p.evaluate('localStorage.getItem("arenaPathway.v2")');p.get_by_role('button',name='Club review',exact=True).click();self.assertIn('Packet evidence is hidden',p.locator('#lockedin-stage').inner_text());p.get_by_role('button',name='Parent review',exact=True).click()
  for name in ['NSID result','Box sample clearance','DocuSign acknowledgments','Fiserv readiness']:p.get_by_role('button',name='Simulate '+name,exact=True).click()
  p.get_by_label('I approve only this fictional summary for Example AP Club',exact=True).check();p.get_by_role('button',name='Submit fictional packet to club',exact=True).click();p.get_by_role('button',name='Accept fictional club packet',exact=True).click();p.get_by_role('button',name='Preview fictional handoff',exact=True).click();p.get_by_role('button',name='Simulate provider failure',exact=True).click();self.assertIn('No destination record created',p.locator('#lockedin-feedback').inner_text());p.get_by_role('button',name='Retry fictional handoff',exact=True).click();p.get_by_role('button',name='Retry fictional handoff',exact=True).click();self.assertIn('Sample destination records: 1',p.locator('#lockedin-stage').inner_text());self.screenshot('lockedin-handoff-ipad');p.get_by_role('button',name='Revoke future sample sharing',exact=True).click();p.get_by_role('button',name='Simulate successful handoff',exact=True).click();self.assertIn('Review the accepted packet',p.locator('#lockedin-feedback').inner_text());self.assertEqual(p.evaluate('localStorage.getItem("arenaPathway.v2")'),before);p.get_by_role('button',name='Reset fictional demo',exact=True).click();self.assertFalse(p.get_by_label('I approve only this fictional summary for Example AP Club',exact=True).is_checked())
