  self.nav('Media');p.get_by_role('button',name='Add Media',exact=True).click();p.locator('#media-upload').set_input_files({'name':'race.png','mimeType':'image/png','buffer':base.PNG});p.locator('#media-caption').fill('Fictional race highlight');p.locator('#media-event').select_option(child);p.get_by_role('button',name='Save media',exact=True).click();p.wait_for_selector('.family-media-gallery img');self.assertIn('Preliminary race',p.locator('.family-media-gallery').inner_text())
  p.goto(base.base.BASE+'/my-ap?scenario=local&section=calendar');p.wait_for_selector('#platform-calendar');p.get_by_label('Calendar date',exact=True).fill('2026-11-20');p.get_by_label('Calendar date',exact=True).press('Tab');p.wait_for_selector('#platform-calendar .ap-activity');self.assertIn('Preliminary race',p.locator('#platform-calendar').inner_text());self.assertEqual(len(self.state()['profiles'][0]['plans']),1);self.assertNotIn('recruiting',self.state()['profiles'][0]['modules']);self.screenshot('shared-calendar-ipad');p.goto(base.base.BASE+'/my-pathway#schedules');p.wait_for_selector('#schedule-list article');row=p.locator('#schedule-list article').filter(has=p.get_by_role('heading',name='Synthetic weekend meet · Preliminary race',exact=True));row.locator('summary').click();p.once('dialog',lambda d:d.accept());row.get_by_role('button',name='Delete session',exact=True).click();p.wait_for_function('()=>JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].plans[0].sessions.length===1');self.nav('Media');p.wait_for_selector('.family-media-gallery img');item=p.locator('.family-media-gallery .record');item.get_by_text('Edit media details',exact=True).click();self.assertEqual(item.locator('select').input_value(),child);item.locator('input').fill('Retained race highlight');item.get_by_role('button',name='Save media details',exact=True).click();p.reload();p.wait_for_selector('.family-media-gallery img');item=p.locator('.family-media-gallery .record');item.get_by_text('Edit media details',exact=True).click();self.assertEqual(item.locator('select').input_value(),child);self.assertIn('Retained event reference',item.inner_text());self.assertEqual(len(self.state()['profiles'][0]['records']),1)
